function handles(){if(mode!=='build'||tool!=='select'||!selection)return[];const s=ppu(),out=[];if(selection.type==='box'){const b=box(selection.id);if(!b)return[];const f=boxFrame(b),sx=f.q.x>=0?-1:1,sy=f.q.y>=0?-1:1;for(const [key,q,label]of[['width',{x:sx*b.w/2,y:b.shape==='polygon'?b.h*.25:0},'W'],['height',{x:b.shape==='polygon'?b.w*.25:0,y:sy*b.h/2},'H'],['rotate',{x:0,y:-b.h/2-43/s},'↻']]){if(b.shape==='circle'&&key==='height')continue;const v=E.rotate(q,b.angle),pos=toScreen({x:b.x+v.x,y:b.y+v.y});out.push({key,pos,label:b.shape==='circle'&&key==='width'?'R':label,type:'box',id:b.id,side:key==='width'?sx:sy})}if(b.shape==='polygon')b.vertices.forEach((v,i)=>out.push({key:'vertex'+i,index:i,pos:toScreen(E.anchor(b,v)),label:'',type:'box',id:b.id}))}else if(selection.type==='pin'){const j=pin(selection.id);if(!j)return[];const child=box(pinChild(j)),pivot=toScreen(jointPoint(j)),base=child.angle+(child.h>=child.w?Math.PI/2:0),sign=child.id===j.b?1:-1;for(const [key,angle,r,label]of[['low',base+j.low*Math.PI/180*sign,44,j.low+'°'],['high',base+j.high*Math.PI/180*sign,44,j.high+'°'],['rotate',base,68,'↻']]){if((j.limits===false||E.jointMode(j)==='motor')&&key!=='rotate')continue;out.push({key,pos:{x:pivot.x+Math.cos(angle)*r*jointMetrics(j).controls,y:pivot.y+Math.sin(angle)*r*jointMetrics(j).controls},label,type:'pin',id:j.id,base,sign,child:child.id})};out.push({key:'pivot',pos:pivot,label:'',type:'pin',id:j.id})}else{const m=muscle(selection.id);if(!m)return[];const a=toScreen(jointPoint(m)),b=toScreen(jointPoint(m,'b')),len=Math.max(1,Math.hypot(b.x-a.x,b.y-a.y)),normal={x:-(b.y-a.y)/len,y:(b.x-a.x)/len};out.push({key:'a',pos:a,label:'A',type:'muscle',id:m.id},{key:'b',pos:b,label:'B',type:'muscle',id:m.id},{key:'rest',pos:{x:(a.x+b.x)/2+normal.x*40,y:(a.y+b.y)/2+normal.y*40},label:(len/s*(m.restScale||1)).toFixed(2)+' m',normal,type:'muscle',id:m.id})}return out}
