function clampToBox(b,p){if(b.shape==='polygon'){if(contains(b,p))return p;const v=corners(b);return v.map((a,i)=>segmentPoint(p,a,v[(i+1)%v.length])).reduce((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)<Math.hypot(b.x-p.x,b.y-p.y)?a:b)}const q=E.localAnchor(b,p);if(b.shape==='circle'){const len=Math.hypot(q.x,q.y);return E.anchor(b,len>.5?{x:q.x*.5/len,y:q.y*.5/len}:q)}return E.anchor(b,{x:clamp(q.x,-.5,.5),y:clamp(q.y,-.5,.5)})}
function beginEdit(kind,p,extra={}){gesture={kind,start:p,original:E.clone(model),moved:false,...extra}}
function beginPose(id,p){const h=hierarchy(id);if(h.root===id){beginEdit('move',p,{ids:h.component});return}beginEdit('pose',p,{id,draft:E.createDraft(model,id,p)})}
function beginHandle(h,p){if(h.type==='box'){const b=box(h.id),f=boxFrame(b);if(h.key.startsWith('vertex'))beginEdit('vertex',p,{id:b.id,index:h.index});else if(h.key==='rotate'){if(f.root===b.id)beginEdit('rotate',p,{pivot:{x:b.x,y:b.y},ids:f.component});else beginPose(b.id,p)}else beginEdit('resize',p,{id:b.id,key:h.key,side:h.side,pivot:f.pivot,q:f.q,angle:b.angle})}else if(h.type==='pin'){if(h.key==='rotate')beginPose(h.child,p);else beginEdit(h.key==='pivot'?'pivot':'limit',p,{id:h.id,key:h.key,base:h.base,sign:h.sign})}else beginEdit(h.key==='rest'?'rest':'endpoint',p,{id:h.id,key:h.key,normal:h.normal,initial:muscle(h.id).restScale||1})}
function markMoved(){if(!gesture.moved){checkpoint();gesture.moved=true;invalidate()}}
function copyDraft(){if(gesture?.kind==='pose'&&gesture.moved){gesture.draft.step(3);gesture.draft.apply(model)}}
function updateEdit(p){const g=gesture;if(!g)return;if(!g.moved&&Math.hypot(p.x-g.start.x,p.y-g.start.y)*ppu()<3)return;markMoved();if(g.kind==='move'){for(const b of model.boxes)if(g.ids.has(b.id)){const old=g.original.boxes.find(v=>v.id===b.id);b.x=old.x+p.x-g.start.x;b.y=old.y+p.y-g.start.y}}else if(g.kind==='pose'){g.draft.move(p);copyDraft()}else if(g.kind==='rotate'){const delta=norm(Math.atan2(p.y-g.pivot.y,p.x-g.pivot.x)-Math.atan2(g.start.y-g.pivot.y,g.start.x-g.pivot.x));for(const b of model.boxes)if(g.ids.has(b.id)){const old=g.original.boxes.find(v=>v.id===b.id),v=E.rotate({x:old.x-g.pivot.x,y:old.y-g.pivot.y},delta);b.x=g.pivot.x+v.x;b.y=g.pivot.y+v.y;b.angle=old.angle+delta}}else if(g.kind==='vertex'){const b=box(g.id),q=E.localAnchor(b,p),vertices=E.clone(b.vertices);vertices[g.index]={x:clamp(q.x,-.5,.5),y:clamp(q.y,-.5,.5)};if(E.validPolygon(vertices))b.vertices=vertices}else if(g.kind==='resize'){const previous=E.clone(model);model=E.clone(g.original);const b=box(g.id),q=E.rotate({x:p.x-g.pivot.x,y:p.y-g.pivot.y},-g.angle),axis=g.key==='width'?'x':'y',den=g.side*.5-g.q[axis];b[g.key==='width'?'w':'h']=clamp(q[axis]/den,.2,4);if(b.shape==='circle')b.h=b.w;reflow();if(model.pins.some(j=>{const a=jointPoint(j),b=jointPoint(j,'b');return Math.hypot(a.x-b.x,a.y-b.y)>.045})){model=previous;g.constrained=true}}else if(g.kind==='limit'){const j=pin(g.id),a=jointPoint(j),value=Math.round(norm(Math.atan2(p.y-a.y,p.x-a.x)-g.base)*180/Math.PI*g.sign);if(g.key==='low')j.low=clamp(value,-170,j.high-5);else j.high=clamp(value,j.low+5,170)}else if(g.kind==='pivot'){const j=pin(g.id),q=constrainPivot(j,p);j.pa=E.localAnchor(box(j.a),q);j.pb=E.localAnchor(box(j.b),q)}else if(g.kind==='endpoint'){const m=muscle(g.id),b=box(m[g.key]),q=clampToBox(b,p);m[g.key==='a'?'pa':'pb']=E.localAnchor(b,q)}else if(g.kind==='rest'){const m=muscle(g.id),delta={x:(p.x-g.start.x)*ppu(),y:(p.y-g.start.y)*ppu()};m.restScale=clamp(g.initial+(delta.x*g.normal.x+delta.y*g.normal.y)/90,.35,2)}refreshSelection()}
function cancelGesture(){if(gesture?.moved&&gesture.original){model=E.clone(gesture.original);history.pop();changed()}gesture=null;pinch=null;pointers.clear();playback?.release()}
function beginPan(p){gesture={kind:'pan',start:p,cx:camera().x,cy:camera().y};if(mode==='test'){followPlay=false;updateFollow()}}
function keyboardHandle(e,h){if(!e.key.startsWith('Arrow'))return;e.preventDefault();checkpoint();const dir=['ArrowRight','ArrowUp'].includes(e.key)?1:-1;if(h.type==='box'){const b=box(h.id);if(h.key.startsWith('vertex')){const v=E.clone(b.vertices),q=v[h.index];q.x=clamp(q.x+(e.key==='ArrowRight'?.02:e.key==='ArrowLeft'?-.02:0),-.5,.5);q.y=clamp(q.y+(e.key==='ArrowDown'?.02:e.key==='ArrowUp'?-.02:0),-.5,.5);if(E.validPolygon(v)){b.vertices=v;E.cleanConnections(model);if(!box(h.id))selection=null}changed();return}if(h.key==='width')b.w=clamp(b.w+dir*.05,.2,4);if(h.key==='height')b.h=clamp(b.h+dir*.05,.2,4);if(b.shape==='circle')b.h=b.w;if(h.key==='rotate'){b.angle+=dir*Math.PI/90}reflow()}else if(h.type==='pin'){const j=pin(h.id);if(h.key==='low')j.low=clamp(j.low+dir,-170,j.high-5);if(h.key==='high')j.high=clamp(j.high+dir,j.low+5,170);if(h.key==='pivot'){const p=jointPoint(j),q=constrainPivot(j,{x:p.x+(e.key==='ArrowRight'?.03:e.key==='ArrowLeft'?-.03:0),y:p.y+(e.key==='ArrowDown'?.03:e.key==='ArrowUp'?-.03:0)});j.pa=E.localAnchor(box(j.a),q);j.pb=E.localAnchor(box(j.b),q)}if(h.key==='rotate'){const id=pinChild(j),p=jointPoint(j),b=box(id),v={x:b.x-p.x,y:b.y-p.y},r=E.rotate(v,dir*Math.PI/90),d=E.createDraft(model,id,{x:b.x,y:b.y});d.move({x:p.x+r.x,y:p.y+r.y});d.step(20);d.apply(model)}}else if(h.key==='rest'){const m=muscle(h.id);m.restScale=clamp((m.restScale||1)+dir*.05,.35,2)}else if(h.key==='a'||h.key==='b'){const m=muscle(h.id),p=jointPoint(m,h.key),b=box(m[h.key]),q=clampToBox(b,{x:p.x+(e.key==='ArrowRight'?.03:e.key==='ArrowLeft'?-.03:0),y:p.y+(e.key==='ArrowDown'?.03:e.key==='ArrowUp'?-.03:0)});m[h.key==='a'?'pa':'pb']=E.localAnchor(b,q)}changed()}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;e.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);const sp=screen(e);pointers.set(e.pointerId,sp);if(pointers.size===2){if(gesture?.moved&&gesture.original){model=gesture.original;history.pop();changed()}playback?.release();gesture=null;const[a,b]=[...pointers.values()],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};if(mode==='test'){followPlay=false;updateFollow()}pinch={distance:Math.hypot(a.x-b.x,a.y-b.y),z:camera().z,world:toWorld(mid)};return}if(pointers.size>2)return;const p=toWorld(sp);if(mode==='test'){if(playback.grab(p)){gesture={kind:'grab'};return}beginPan(sp);return}if(mode==='train'||tool==='pan'||spaceDown||e.button===1){beginPan(sp);return}if(tool==='select'){const h=hitHandle(sp);if(h){if(h.type==='pin')$('jointSettings').hidden=false;beginHandle(h,p);return}}if(tool==='pin'){addPinAt(p);return}if(tool==='muscle'){addMusclePoint(p);return}const j=pinAt(p),b=boxesAt(p)[0],m=muscleAt(p);if(tool==='delete'){if(j)pick({type:'pin',id:j.id});else if(m)pick({type:'muscle',id:m.id});else if(b)pick({type:'box',id:b.id});else return;removeSelected();return}if(['draw','circle','polygon'].includes(tool)){gesture={kind:'draw',shape:tool==='draw'?'box':tool,start:p,current:p};return}if(j){pick({type:'pin',id:j.id});beginHandle({type:'pin',key:'pivot',id:j.id},p);return}if(m){pick({type:'muscle',id:m.id});return}if(b){pick({type:'box',id:b.id});beginPose(b.id,p);return}pick(null);beginPan(sp)});
canvas.addEventListener('pointermove',e=>{const sp=screen(e),p=toWorld(sp);hover=p;if(pointers.has(e.pointerId))pointers.set(e.pointerId,sp);if(pinch&&pointers.size>=2){const[a,b]=[...pointers.values()],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2},c=camera();c.z=clamp(pinch.z*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,pinch.distance),.005,3.5);c.x=pinch.world.x-(mid.x-view.w/2)/ppu();c.y=pinch.world.y-(mid.y-view.h/2)/ppu();return}if(!gesture)return;if(gesture.kind==='pan'){camera().x=gesture.cx-(sp.x-gesture.start.x)/ppu();camera().y=gesture.cy-(sp.y-gesture.start.y)/ppu()}else if(gesture.kind==='draw')gesture.current=p;else if(gesture.kind==='grab')playback.move(p);else updateEdit(p)});
function pointerEnd(e,cancel=false){pointers.delete(e.pointerId);if(pinch){pinch=null;gesture=null;return}if(cancel){cancelGesture();return}if(gesture?.kind==='draw'){const a=gesture.start,b=gesture.current;if(Math.hypot(a.x-b.x,a.y-b.y)*ppu()>8){const circle=gesture.shape==='circle',diameter=2*Math.hypot(a.x-b.x,a.y-b.y);addBox(circle?a.x:(a.x+b.x)/2,circle?a.y:(a.y+b.y)/2,circle?diameter:Math.abs(a.x-b.x),circle?diameter:Math.abs(a.y-b.y),gesture.shape)}}if(gesture?.kind==='grab')playback.release();if(gesture?.moved){if(gesture.kind==='vertex'){E.cleanConnections(model);if(selection?.type==='box'&&!box(selection.id))selection=null}if(gesture.constrained)toast('Loop constrains this size.');changed()}gesture=null}
canvas.addEventListener('pointerup',e=>pointerEnd(e));canvas.addEventListener('pointercancel',e=>pointerEnd(e,true));canvas.addEventListener('wheel',e=>{e.preventDefault();setZoom(camera().z*Math.exp(-e.deltaY*.0015),screen(e))},{passive:false});
document.addEventListener('wheel',e=>{if(e.ctrlKey)e.preventDefault()},{passive:false});for(const t of ['gesturestart','gesturechange','gestureend'])document.addEventListener(t,e=>e.preventDefault(),{passive:false});
function pauseText(){$('pauseTrain').textContent=trainPaused?'Train':'Stop';$('pauseTrain').setAttribute('aria-label',trainPaused?'Train':'Stop');$('pausePlay').textContent=playPaused?'▶':'Ⅱ';$('pausePlay').setAttribute('aria-label',playPaused?'Resume playback':'Pause playback')}
function brainOptions(){return{hidden:clamp(Math.round(+$('brainNeurons').value||8),1,32),layers:clamp(Math.round(+$('brainLayers').value||1),1,4)}}
function freshEvolution(seed=null){evolution?.dispose?.();model.brain||={hidden:8,layers:1};seed||=visibleGenome();const e=new E.ParallelEvolution(model,{population:+$('population').value,duration:+$('duration').value,...opts(),seed,rough,swimming,goal:trainingGoal()});e.onProgress=n=>{actualSteps+=n;fastBatches++};e.onGeneration=()=>{if(e!==evolution)return;captureChampion(e);updateUI()};e.onError=()=>{trainPaused=true;pauseText();$('actualSpeed').textContent='Training stopped';toast('Training worker stopped. Reset brain to retry.')};return e}
function testGenome(){return visibleGenome()}
function resetTest(){playback?.release();playback=new E.Playback(model,testGenome(),{rough,swimming,goal:trainingGoal(),terrainSeed:E.randomTerrainSeed(playback?.terrainSeed)});playback.setCommand(joystickValue.x,joystickValue.y);playPaused=false;cameras.test.x=leadOffset();cameras.test.y=-1.9;updateFollow();pauseText()}
function switchMode(next){if(next===mode)return;if(mode==='test')releaseJoystick();if(next==='train'){const error=E.validate(model);if(error){toast(error);return}if(!evolution){evolution=freshEvolution();cameras.train.x=leadOffset();cameras.train.y=-1.9}}if(next==='test'){if(!usingBest){const candidate=alternateModel();if(candidate&&!E.validate(candidate))toggleBest(true)}const error=E.validate(model);if(error){toast(error);return}resetTest()}if(next==='brain'){if(mode==='train'||mode==='test')brainSource=mode;else brainSource='test'}cancelGesture();mode=next;budget=0;last=0;$('settings').hidden=true;$('testSettings').hidden=true;$('environment').hidden=true;$('jointSettings').hidden=true;for(const m of ['build','train','test','brain']){document.querySelectorAll('.'+m+'-ui').forEach(el=>el.hidden=m!==mode);$(m+'Tab').classList.toggle('active',m===mode);if(m===mode)$(m+'Tab').setAttribute('aria-current','page');else $(m+'Tab').removeAttribute('aria-current')}canvas.style.visibility=mode==='brain'?'hidden':'visible';syncTrainingWorkers();sourceUI();refreshSelection();pauseText();updateUI()}
function applyTrainingSettings(){if(!evolution)return;evolution.configure({population:+$('population').value,duration:+$('duration').value});brainPlayback=null;brainGenome=null;brainData=null;budget=0;updateUI()}
function resetBody(){if(!evolution){clearBest();updateUI();return}const seed=evolution.resetBodies();clearBest();adoptGenome(seed);sourceDirty=true;playback=null;brainPlayback=null;brainGenome=null;brainData=null;histogramFrame=null;distanceChartKey='';stageDrawnState=null;stageDrawnMode='';budget=0;pauseText();updateUI()}
$('resetBodyTrain').onclick=resetBody;
function resetBrain(){const seed=E.randomGenome(model,visibleGenome(),{body:false,brain:true});clearBest();adoptGenome(seed);sourceDirty=true;if(evolution)evolution=freshEvolution(seed);budget=0;if(mode==='test'&&playback)playback.resetBrain(seed);else playback=null;pauseText();updateUI()}
document.querySelectorAll('[data-tool]').forEach(el=>el.onclick=()=>setTool(el.dataset.tool));$('undoBtn').onclick=undo;$('exampleBtn').onclick=()=>{checkpoint();model={...E.example(),brain:model.brain};selection={type:'box',id:1};changed();fit()};$('clearBtn').onclick=()=>{checkpoint();clearBest();model={boxes:[],pins:[],muscles:[],brain:model.brain};selection=null;changed()};for(const m of ['build','train','test','brain'])$(m+'Tab').onclick=()=>switchMode(m);$('pauseTrain').onclick=()=>{trainPaused=!trainPaused;budget=0;pauseText()};$('pausePlay').onclick=()=>{playPaused=!playPaused;budget=0;pauseText()};$('resetPlay').onclick=()=>{resetTest();fit()};$('resetBrainTrain').onclick=$('resetBrainTest').onclick=resetBrain;document.querySelectorAll('[data-rough]').forEach(el=>el.onchange=()=>setRough(el.checked));$('settingsBtn').onclick=()=>{$('environment').hidden=true;$('settings').hidden=!$('settings').hidden};$('closeSettings').onclick=()=>$('settings').hidden=true;$('testSettingsBtn').onclick=()=>{$('environment').hidden=true;$('testSettings').hidden=!$('testSettings').hidden};$('closeTestSettings').onclick=()=>$('testSettings').hidden=true;

function setJoystick(x,y){const length=Math.max(1,Math.hypot(x,y));joystickValue={x:x/length,y:y/length};$('joystickThumb').style.transform=`translate(calc(-50% + ${joystickValue.x*37}px),calc(-50% + ${joystickValue.y*37}px))`;playback?.setCommand(joystickValue.x,joystickValue.y)}
function releaseJoystick(){const id=joystickPointer;joystickPointer=null;joystickKeys.clear();$('joystick').classList.remove('dragging');if(id!==null&&$('joystick').hasPointerCapture(id))$('joystick').releasePointerCapture(id);setJoystick(0,0)}
function moveJoystick(e){const r=$('joystick').getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/37,y=(e.clientY-r.top-r.height/2)/37;if(Math.hypot(x,y)<.06)x=y=0;setJoystick(x,y)}
$('joystick').onpointerdown=e=>{if(joystickPointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();e.stopPropagation();joystickPointer=e.pointerId;e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.classList.add('dragging');e.currentTarget.focus({preventScroll:true});moveJoystick(e)};
$('joystick').onpointermove=e=>{if(e.pointerId!==joystickPointer)return;e.preventDefault();e.stopPropagation();moveJoystick(e)};
for(const event of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(event,e=>{if(e.pointerId===joystickPointer){e.preventDefault();e.stopPropagation();releaseJoystick()}});
for(const event of ['keydown','keyup'])$('joystick').addEventListener(event,e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();e.stopPropagation();if(event==='keydown')joystickKeys.add(e.key);else joystickKeys.delete(e.key);setJoystick(Number(joystickKeys.has('ArrowRight'))-Number(joystickKeys.has('ArrowLeft')),Number(joystickKeys.has('ArrowDown'))-Number(joystickKeys.has('ArrowUp')))});
$('joystick').onblur=()=>{if(joystickPointer===null)releaseJoystick()};window.addEventListener('blur',releaseJoystick);document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseJoystick()});
function trainingContext(){return mode==='train'||(mode==='brain'&&brainSource==='train')}
function trainingPreview(){return !$('maxTrain').checked}
function fastTrainingWanted(){return!!evolution&&trainingContext()&&!trainPaused&&!trainingPreview()&&!document.hidden}
function syncTrainingWorkers(){evolution?.setRunning(trainingContext()&&!trainPaused&&!document.hidden,trainingPreview(),1)}
document.addEventListener('visibilitychange',syncTrainingWorkers);
$('neuralEvolution').onchange=()=>{$('weightSize').disabled=!$('neuralEvolution').checked;evolution?.setOptions(opts())};
$('physicsEvolution').onchange=()=>{for(const id of ['bodySize','rotationSize','vertexSize','partChance'])$(id).disabled=!$('physicsEvolution').checked;evolution?.setOptions(opts())};
$('maxTrain').onchange=()=>{budget=0;last=0;histogramFrame=null;stageDrawnState=null;stageDrawnMode='';actualSteps=0;actualSince=performance.now();renderStage();updateUI();syncTrainingWorkers()};
