$('followBtn').onclick=()=>{followPlay=!followPlay;updateFollow()};
$('closeJointSettings').onclick=()=>$('jointSettings').hidden=true;document.querySelectorAll('[data-joint-mode]').forEach(el=>el.onclick=()=>{const j=selection?.type==='pin'?pin(selection.id):null;if(!j)return;checkpoint();j.mode=el.dataset.jointMode;j.powered=j.mode!=='unpowered';changed()});
for(const id of ['jointLow','jointHigh'])$(id).onchange=()=>{const j=selection?.type==='pin'?pin(selection.id):null;if(!j)return;const value=Number($(id).value);if(!Number.isFinite(value)){refreshSelection();return}checkpoint();if(id==='jointLow')j.low=clamp(Math.round(value),-170,j.high-5);else j.high=clamp(Math.round(value),j.low+5,170);changed()};
function recordMatches(record){return record&&!!record.swimming===swimming&&record.goal===trainingGoal()&&(swimming||!!record.rough===rough)}
function openEnvironment(){const panel=$('environment');$('settings').hidden=true;$('testSettings').hidden=true;panel.dataset.mode=mode;panel.hidden=!panel.hidden}
$('environmentTrain').onclick=$('environmentTest').onclick=openEnvironment;$('closeEnvironment').onclick=()=>$('environment').hidden=true;
$('swimming').onchange=()=>setSwimming($('swimming').checked);
