$('brainNeurons').oninput=$('brainLayers').oninput=pendingBrain;$('confirmBrain').onclick=()=>{applyBrainOptions();pendingBrain()};
$('population').oninput=()=>{refreshTrainingDials();applyTrainingSettings()};$('duration').onchange=applyTrainingSettings;$('playSpeed').onchange=()=>{budget=0};

